import * as mammoth from 'mammoth';
import {
  ExtractedBlock,
  ExtractedDocument,
  DocumentExtractionWarning,
  DocumentValidationError,
} from '../types';

interface ParsedElement {
  tag: string;
  text: string;
  level?: number;
}

/**
 * Safely parses HTML generated by Mammoth into structured elements
 * without rendering anything into the page or executing scripts.
 */
function parseMammothHtml(html: string): ParsedElement[] {
  const elements: ParsedElement[] = [];

  if (typeof DOMParser !== 'undefined') {
    const parser = new DOMParser();
    const doc = parser.parseFromString(html, 'text/html');
    const childNodes = doc.body.children;

    for (let i = 0; i < childNodes.length; i++) {
      const el = childNodes[i];
      const tag = el.tagName.toLowerCase();
      const text = (el.textContent || '').trim();
      if (!text) continue;

      const headingMatch = tag.match(/^h([1-6])$/);
      if (headingMatch) {
        elements.push({
          tag: 'heading',
          text,
          level: parseInt(headingMatch[1], 10),
        });
      } else {
        // p, blockquote, li, table, etc.
        elements.push({
          tag: 'p',
          text,
        });
      }
    }
  } else {
    // Regex fallback for environments without DOMParser
    const tagRegex = /<(h[1-6]|p|blockquote|li)[^>]*>([\s\S]*?)<\/\1>/gi;
    let match: RegExpExecArray | null;

    while ((match = tagRegex.exec(html)) !== null) {
      const tag = match[1].toLowerCase();
      // Strip any inner html tags
      const text = match[2].replace(/<[^>]+>/g, '').trim();
      if (!text) continue;

      const headingMatch = tag.match(/^h([1-6])$/);
      if (headingMatch) {
        elements.push({
          tag: 'heading',
          text,
          level: parseInt(headingMatch[1], 10),
        });
      } else {
        elements.push({
          tag: 'p',
          text,
        });
      }
    }
  }

  return elements;
}

/**
 * Extracts structured blocks from a Word (.docx) document.
 * Safely preserves headings, paragraph boundaries, and source locations.
 */
export async function extractFromDocx(
  input: ArrayBuffer | Blob,
  fileName = 'document.docx',
  fileSize = 0
): Promise<ExtractedDocument> {
  let arrayBuffer: ArrayBuffer;

  if (input instanceof Blob) {
    arrayBuffer = await input.arrayBuffer();
  } else {
    arrayBuffer = input;
  }

  if (!arrayBuffer || arrayBuffer.byteLength === 0) {
    throw new DocumentValidationError(
      'EMPTY_FILE',
      'The Word document file is empty (0 bytes).',
      'Please select a valid .docx file that contains content.'
    );
  }

  let htmlResult: { value: string; messages: Array<{ type: string; message: string }> };

  const mammothOptions: any = {};
  if (typeof Buffer !== 'undefined') {
    mammothOptions.buffer = Buffer.from(arrayBuffer);
  } else {
    mammothOptions.arrayBuffer = arrayBuffer;
  }

  try {
    htmlResult = await mammoth.convertToHtml(mammothOptions);
  } catch (err: any) {
    const message = err?.message || '';
    if (message.includes('Can\'t find end of central directory') || message.includes('corrupted') || message.includes('zip')) {
      throw new DocumentValidationError(
        'CORRUPTED_FILE',
        'Unable to parse Word document. The file may be corrupt or in an older binary format (.doc).',
        'Please verify that this is a modern .docx file created in Microsoft Word, Google Docs, or Pages.'
      );
    }
    throw new DocumentValidationError(
      'CORRUPTED_FILE',
      `Failed to parse .docx file: ${message || 'Invalid format'}`,
      'Try saving the document again as a clean .docx file and re-uploading.'
    );
  }

  const parsedElements = parseMammothHtml(htmlResult.value);

  if (parsedElements.length === 0) {
    // Try extractRawText as fallback
    const rawResult = await mammoth.extractRawText(mammothOptions).catch(() => ({ value: '' }));
    if (!rawResult.value.trim()) {
      throw new DocumentValidationError(
        'NO_TEXT_FOUND',
        'No readable text could be extracted from this Word document.',
        'Ensure the document contains typed prose, and does not contain only images or blank pages.'
      );
    }
  }

  const blocks: ExtractedBlock[] = [];
  const warnings: DocumentExtractionWarning[] = [];

  // Check for mammoth conversion notices (e.g. unhandled images/shapes)
  if (htmlResult.messages && htmlResult.messages.length > 0) {
    const ignoredElements = htmlResult.messages.filter((m) =>
      m.message.toLowerCase().includes('unrecognised') || m.message.toLowerCase().includes('not supported')
    );
    if (ignoredElements.length > 0) {
      warnings.push({
        code: 'UNSUPPORTED_ELEMENTS',
        message: 'Some complex formatting, embedded shapes, or unsupported elements were skipped during text extraction.',
      });
    }
  }

  let fullText = '';
  let cursor = 0;
  let paragraphIndex = 0;
  let currentSectionHeading: string | undefined = undefined;
  let currentSectionLevel: number | undefined = undefined;

  for (let i = 0; i < parsedElements.length; i++) {
    const item = parsedElements[i];
    const text = item.text.trim();
    if (!text) continue;

    if (fullText.length > 0) {
      fullText += '\n\n';
      cursor += 2;
    }

    const start = cursor;
    fullText += text;
    cursor += text.length;
    const end = cursor;

    if (item.tag === 'heading') {
      currentSectionHeading = text;
      currentSectionLevel = item.level;

      blocks.push({
        id: `block-${blocks.length + 1}`,
        type: 'heading',
        level: item.level,
        sectionHeading: text,
        text,
        startIndex: start,
        endIndex: end,
        paragraphIndex: paragraphIndex++,
      });
    } else {
      blocks.push({
        id: `block-${blocks.length + 1}`,
        type: 'paragraph',
        sectionHeading: currentSectionHeading,
        level: currentSectionLevel,
        text,
        startIndex: start,
        endIndex: end,
        paragraphIndex: paragraphIndex++,
      });
    }
  }

  if (blocks.length === 0) {
    throw new DocumentValidationError(
      'NO_TEXT_FOUND',
      'No text blocks were extracted from this Word document.',
      'Check that the document has readable text.'
    );
  }

  return {
    id: `doc-${Date.now()}-${Math.random().toString(36).substring(2, 7)}`,
    fileName,
    fileSize: fileSize || arrayBuffer.byteLength,
    format: 'docx',
    extractedAt: new Date().toISOString(),
    fullText,
    blocks,
    hasHeadings: blocks.some((b) => b.type === 'heading'),
    warnings,
  };
}
